package app.plugxaura.iptv;

import android.content.*;
import android.content.pm.PackageManager;
import android.os.*;
import android.view.*;
import android.widget.*;
import androidx.appcompat.app.AppCompatActivity;
import com.google.gson.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;
import okhttp3.*;

public class SettingsActivity extends AppCompatActivity {
    private LinearLayout root;private Spinner quality,protocol;private EditText host,port;private Switch enableProxy,boot,light;
    private final ArrayList<View> remoteOrder=new ArrayList<>(),headerActions=new ArrayList<>();
    private <T extends View> T remote(T view){view.setId(View.generateViewId());view.setFocusable(true);if(view instanceof Switch||view instanceof Spinner){Ui.focus(view,this);view.setPadding(Ui.dp(this,14),Ui.dp(this,6),Ui.dp(this,14),Ui.dp(this,6));}remoteOrder.add(view);return view;}
    private void wireRemoteFocus(){
        if(remoteOrder.isEmpty())return;
        for(int i=0;i<remoteOrder.size();i++){View current=remoteOrder.get(i);current.setNextFocusUpId(i==0?(headerActions.isEmpty()?current.getId():headerActions.get(1).getId()):remoteOrder.get(i-1).getId());current.setNextFocusDownId(i+1<remoteOrder.size()?remoteOrder.get(i+1).getId():current.getId());}
        for(int i=0;i<headerActions.size();i++){View current=headerActions.get(i);current.setNextFocusDownId(remoteOrder.get(0).getId());current.setNextFocusLeftId(headerActions.get(Math.max(0,i-1)).getId());current.setNextFocusRightId(headerActions.get(Math.min(headerActions.size()-1,i+1)).getId());}
    }
    @Override public void onCreate(Bundle b){super.onCreate(b);Ui.applyTheme(this);ScrollView sc=new ScrollView(this);sc.setBackgroundColor(Ui.BG);sc.setDescendantFocusability(ViewGroup.FOCUS_AFTER_DESCENDANTS);root=Ui.column(this);root.setPadding(Ui.dp(this,16),Ui.dp(this,12),Ui.dp(this,16),Ui.dp(this,22));sc.addView(root);setContentView(sc);addHomeHeader(sc);Button back=remote(Ui.button(this,"<- Home"));root.addView(back,Ui.margins(this,-1,50,2));back.setOnClickListener(v->finish());title("Settings");
        light=remote(new Switch(this));light.setText("Light theme");light.setTextColor(Ui.TEXT);light.setChecked(PlugXApp.prefs(this).getBoolean("light",false));root.addView(light,Ui.margins(this,-1,54,4));light.setOnCheckedChangeListener((b2,yes)->{PlugXApp.prefs(this).edit().putBoolean("light",yes).apply();recreate();});
        title("Live TV picture quality");String[] labels={"Auto (recommended)","360p","480p","720p HD","1080p Full HD","1440p QHD","4K / 2160p"};int[] heights={0,360,480,720,1080,1440,2160};quality=remote(new Ui.RemoteSpinner(this,labels));int value=PlugXApp.prefs(this).getInt("quality",0);for(int i=0;i<heights.length;i++)if(value==heights[i])quality.setSelection(i);root.addView(quality,Ui.margins(this,-1,54,4));quality.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> a){}public void onItemSelected(android.widget.AdapterView<?> a,View v,int pos,long id){PlugXApp.prefs(SettingsActivity.this).edit().putInt("quality",heights[pos]).apply();}});
        title("Live TV proxy");JsonObject preset=PlugXApp.object(PlugXApp.catalog(),"proxy_preset");String pname=PlugXApp.str(preset,"name","India proxy"),phost=PlugXApp.str(preset,"host","");if(!phost.isEmpty()){Button use=remote(Ui.button(this,"Use preset: "+pname));root.addView(use,Ui.margins(this,-1,54,4));use.setOnClickListener(v->{host.setText(phost);port.setText(PlugXApp.str(preset,"port",""));String type=PlugXApp.str(preset,"type","socks5");protocol.setSelection(type.equals("http")?1:type.equals("https")?2:0);testProxy();});}
        protocol=remote(new Ui.RemoteSpinner(this,new String[]{"SOCKS5","HTTP","HTTPS CONNECT"}));String selected=PlugXApp.prefs(this).getString("proxy_type","socks5");protocol.setSelection(selected.equals("http")?1:selected.equals("https")?2:0);root.addView(protocol,Ui.margins(this,-1,50,4));
        host=remote(Ui.edit(this,"Proxy host or IP"));host.setText(PlugXApp.prefs(this).getString("proxy_host",""));root.addView(host,Ui.margins(this,-1,54,4));port=remote(Ui.edit(this,"Port"));port.setInputType(2);int savedPort=PlugXApp.prefs(this).getInt("proxy_port",0);if(savedPort>0)port.setText(String.valueOf(savedPort));root.addView(port,Ui.margins(this,-1,54,4));
        enableProxy=remote(new Switch(this));enableProxy.setText("Use proxy for Live TV");enableProxy.setTextColor(Ui.TEXT);enableProxy.setChecked(PlugXApp.prefs(this).getBoolean("proxy_enabled",false));root.addView(enableProxy,Ui.margins(this,-1,50,4));Button test=remote(Ui.button(this,"Test connection & latency")),save=remote(Ui.button(this,"Save proxy"));root.addView(test,Ui.margins(this,-1,52,4));root.addView(save,Ui.margins(this,-1,52,4));test.setOnClickListener(v->testProxy());save.setOnClickListener(v->{int p=parsePort();if(host.getText().toString().trim().isEmpty()&&enableProxy.isChecked()){Ui.alert(this,"Proxy","Enter proxy host first.");return;}PlugXApp.prefs(this).edit().putString("proxy_host",host.getText().toString().trim()).putInt("proxy_port",p).putString("proxy_type",proxyType()).putBoolean("proxy_enabled",enableProxy.isChecked()).apply();Toast.makeText(this,"Proxy settings saved",Toast.LENGTH_SHORT).show();});
        title("TV startup");boot=remote(new Switch(this));boot.setText("Open PlugX IPTV when TV starts");boot.setTextColor(Ui.TEXT);boot.setChecked(PlugXApp.prefs(this).getBoolean("boot_tv",false));root.addView(boot,Ui.margins(this,-1,52,4));boot.setOnCheckedChangeListener((b2,yes)->PlugXApp.prefs(this).edit().putBoolean("boot_tv",yes).apply());
        title("App update");TextView version=Ui.muted(this,"Installed v"+BuildConfig.VERSION_NAME+" (code "+BuildConfig.VERSION_CODE+")",15);root.addView(version,Ui.margins(this,-1,38,4));Button update=remote(Ui.button(this,"Check for update"));root.addView(update,Ui.margins(this,-1,52,4));update.setOnClickListener(v->checkUpdate());Button logout=remote(Ui.button(this,"Sign out"));root.addView(logout,Ui.margins(this,-1,52,4));logout.setOnClickListener(v->PlugXApp.request(this,"logout",null,(r,e)->{PlugXApp.prefs(this).edit().remove("token").apply();startActivity(new Intent(this,LoginActivity.class));finishAffinity();}));
        wireRemoteFocus();if(getPackageManager().hasSystemFeature(PackageManager.FEATURE_LEANBACK))back.requestFocus();
    }
    private void addHomeHeader(ScrollView scroll){
        JsonObject data=PlugXApp.catalog();int widthDp=(int)(getResources().getDisplayMetrics().widthPixels/getResources().getDisplayMetrics().density);boolean wide=widthDp>=600;
        LinearLayout top=Ui.row(this);android.widget.ImageView logo=new android.widget.ImageView(this);logo.setImageResource(R.drawable.plugx_logo);top.addView(logo,Ui.margins(this,wide?56:64,wide?56:64,3));LinearLayout names=Ui.column(this);String name=PlugXApp.str(PlugXApp.object(data,"user"),"display_name","");TextView welcome=Ui.text(this,name.isEmpty()?"PLUG X IPTV":"Welcome, "+name,wide?18:22,true);welcome.setSingleLine(true);welcome.setEllipsize(android.text.TextUtils.TruncateAt.END);names.addView(welcome);TextView sync=Ui.muted(this,Ui.lastSync(this),wide?11:13);sync.setSingleLine(true);sync.setEllipsize(android.text.TextUtils.TruncateAt.END);names.addView(sync);TextView premium=Ui.text(this,"  PLUG X PREMIUM",11,true);premium.setTextColor(0xff8b1c35);premium.setLetterSpacing(.09f);premium.setPadding(Ui.dp(this,9),0,Ui.dp(this,9),0);premium.setBackground(Ui.shape(0xffffe8b7,0xffbd8a35,Ui.dp(this,10)));names.addView(premium,Ui.margins(this,-2,26,2));top.addView(names,new LinearLayout.LayoutParams(0,-2,1));
        LinearLayout actions=Ui.row(this);Button notice=Ui.button(this,"Notices"),settings=Ui.button(this,"Settings"),refresh=Ui.button(this,"Refresh"),logout=Ui.button(this,"Logout");for(Button button:new Button[]{notice,settings,refresh,logout}){button.setId(View.generateViewId());headerActions.add(button);button.setTextSize(wide?11:widthDp<420?11:13);button.setPadding(Ui.dp(this,3),0,Ui.dp(this,3),0);button.setMinWidth(0);button.setMinimumWidth(0);LinearLayout.LayoutParams p=wide?new LinearLayout.LayoutParams(Ui.dp(this,widthDp<780?74:86),Ui.dp(this,42)):new LinearLayout.LayoutParams(0,Ui.dp(this,44),1);p.setMargins(Ui.dp(this,3),0,Ui.dp(this,3),0);actions.addView(button,p);}
        if(wide){top.addView(actions);root.addView(top,Ui.margins(this,-1,68,2));}else{root.addView(top);root.addView(actions,Ui.margins(this,-1,50,2));}
        settings.setOnClickListener(v->scroll.smoothScrollTo(0,0));notice.setOnClickListener(v->{JsonArray items=PlugXApp.array(PlugXApp.catalog(),"notices");StringBuilder message=new StringBuilder();for(JsonElement e:items){JsonObject n=e.getAsJsonObject();message.append("* ").append(PlugXApp.str(n,"title","")).append("\n").append(PlugXApp.str(n,"body","")).append("\n\n");}Ui.alert(this,"Notices",message.length()==0?"No notices yet.":message.toString());});refresh.setOnClickListener(v->{refresh.setEnabled(false);refresh.setText("Updating...");PlugXApp.request(this,"bootstrap",null,(result,error)->{refresh.setEnabled(true);refresh.setText("Refresh");if(error==null){PlugXApp.catalog(this,result);Toast.makeText(this,"Channels are up to date",Toast.LENGTH_SHORT).show();}else Ui.alert(this,"Refresh",error.getMessage());});});logout.setOnClickListener(v->new androidx.appcompat.app.AlertDialog.Builder(this).setTitle("Sign out?").setMessage("You can sign in again with your user ID and password.").setNegativeButton("Stay",null).setPositiveButton("Sign out",(dialog,which)->PlugXApp.request(this,"logout",null,(result,error)->{PlugXApp.prefs(this).edit().remove("token").apply();startActivity(new Intent(this,LoginActivity.class));finishAffinity();})).show());
    }
    private void title(String t){TextView h=Ui.text(this,t,21,true);root.addView(h,Ui.margins(this,-1,46,3));}
    private int parsePort(){try{int p=Integer.parseInt(port.getText().toString());return p>=1&&p<=65535?p:0;}catch(Exception e){return 0;}}
    private String proxyType(){return protocol.getSelectedItemPosition()==1?"http":protocol.getSelectedItemPosition()==2?"https":"socks5";}
    private void testProxy(){String h=host.getText().toString().trim();int p=parsePort();if(h.isEmpty()||p==0){Ui.alert(this,"Proxy","Enter a valid host and port.");return;}long start=System.nanoTime();Toast.makeText(this,"Testing proxy...",Toast.LENGTH_SHORT).show();PlugXApp.WORK.execute(()->{String result;try{Proxy proxy=new Proxy(proxyType().equals("socks5")?Proxy.Type.SOCKS:Proxy.Type.HTTP,new InetSocketAddress(h,p));OkHttpClient client=new OkHttpClient.Builder().proxy(proxy).connectTimeout(8,TimeUnit.SECONDS).readTimeout(10,TimeUnit.SECONDS).build();try(Response r=client.newCall(new Request.Builder().url("https://plugxaura.app/Plugxlive/").get().build()).execute()){long ms=TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-start);result=r.isSuccessful()?"Connected - "+ms+" ms":"Proxy responded HTTP "+r.code()+" - "+ms+" ms";}}catch(Exception e){result="Connection failed: "+e.getClass().getSimpleName();}String text=result;PlugXApp.MAIN.post(()->Ui.alert(this,"Proxy test",text));});}
    private void checkUpdate(){PlugXApp.request(this,"bootstrap",null,(result,error)->{if(error!=null){Ui.alert(this,"Update",error.getMessage());return;}PlugXApp.catalog(this,result);JsonObject update=PlugXApp.object(result,"update");int latest=PlugXApp.integer(update,"version_code",0);if(latest<=BuildConfig.VERSION_CODE){Ui.alert(this,"Up to date","You have the latest version.");return;}String url=PlugXApp.str(update,"apk_path","");if(url.isEmpty()){Ui.alert(this,"Update","APK link is missing.");return;}new androidx.appcompat.app.AlertDialog.Builder(this).setTitle("Update available: "+PlugXApp.str(update,"version_name","")).setMessage(PlugXApp.str(update,"release_notes","A new version is ready.")).setNegativeButton("Later",null).setPositiveButton("Update now",(d,w)->downloadAndInstall(url)).show();});}
    /** FIX: Use system DownloadManager — no REQUEST_INSTALL_PACKAGES needed, avoids Play Store harmful-app flag */
    private void downloadAndInstall(String apkUrl){
        try{
            android.app.DownloadManager dm=(android.app.DownloadManager)getSystemService(DOWNLOAD_SERVICE);
            android.net.Uri uri=android.net.Uri.parse(apkUrl);
            android.app.DownloadManager.Request req=new android.app.DownloadManager.Request(uri);
            req.setTitle("PlugX IPTV Update");
            req.setDescription("Downloading update...");
            req.setNotificationVisibility(android.app.DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED);
            req.setMimeType("application/vnd.android.package-archive");
            req.setDestinationInExternalFilesDir(this,android.os.Environment.DIRECTORY_DOWNLOADS,"plugx-update.apk");
            dm.enqueue(req);
            Toast.makeText(this,"Downloading update. Check your notifications.",Toast.LENGTH_LONG).show();
        }catch(Exception e){Ui.alert(this,"Update","Could not start download: "+e.getMessage());}
    }
}
